-- Phase 5 follow-up: a RevenueEvent can now be a month's membership dues, which has no visit.
-- Generated by `prisma migrate diff`; the section after the marker is hand-written.

-- AlterTable
ALTER TABLE "RevenueEvent" ADD COLUMN     "billingStatus" "BillingStatus",
ADD COLUMN     "membershipId" TEXT,
ADD COLUMN     "periodStart" DATE,
ALTER COLUMN "encounterId" DROP NOT NULL,
ALTER COLUMN "bookingId" DROP NOT NULL,
ALTER COLUMN "serviceId" DROP NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "RevenueEvent_membershipId_periodStart_key" ON "RevenueEvent"("membershipId", "periodStart");

-- AddForeignKey
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_membershipId_fkey" FOREIGN KEY ("membershipId") REFERENCES "Membership"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- =============================================================================
-- HAND-WRITTEN
-- =============================================================================
-- Two kinds of event, and the database refuses a row that is neither. DUES is the only kind without a visit; every other kind has
-- an encounter, a booking and a service, and none of the dues columns. (Every existing row is the second kind.)
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_kind" CHECK (
  ("paymentType" = 'DUES'
     AND "encounterId" IS NULL AND "bookingId" IS NULL AND "serviceId" IS NULL
     AND "membershipId" IS NOT NULL AND "periodStart" IS NOT NULL AND "billingStatus" IS NOT NULL AND "patientId" IS NOT NULL)
  OR ("paymentType" <> 'DUES'
     AND "encounterId" IS NOT NULL AND "bookingId" IS NOT NULL AND "serviceId" IS NOT NULL
     AND "membershipId" IS NULL AND "periodStart" IS NULL AND "billingStatus" IS NULL)
);

-- The money rule, with the third kind: dues are a positive amount billed in full (net = list), with no discount, no credits and no benefit.
ALTER TABLE "RevenueEvent" DROP CONSTRAINT "RevenueEvent_consistent";
ALTER TABLE "RevenueEvent" ADD CONSTRAINT "RevenueEvent_consistent" CHECK (
  "creditsRedeemed" >= 0 AND "netPriceCents" >= 0 AND "discountCents" >= 0
  AND "discountPercent" BETWEEN 0 AND 100
  AND ("listPriceCents" IS NULL OR "listPriceCents" >= 0)
  AND (("paymentType" = 'CASH'   AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0 AND "listPriceCents" IS NOT NULL
        AND "discountCents" <= "listPriceCents" AND "netPriceCents" = "listPriceCents" - "discountCents"
        AND ("discountPercent" > 0 OR "discountCents" = 0))
    OR ("paymentType" = 'MEMBER' AND "memberBenefit" IS NOT NULL AND "netPriceCents" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0
        AND ("memberBenefit" = 'CREDITS') = ("creditsRedeemed" > 0))
    OR ("paymentType" = 'DUES' AND "memberBenefit" IS NULL AND "creditsRedeemed" = 0
        AND "discountPercent" = 0 AND "discountCents" = 0
        AND "listPriceCents" IS NOT NULL AND "listPriceCents" > 0 AND "netPriceCents" = "listPriceCents"))
);
